package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerIdleNaturalSouthStageTest {
 private Crab parent;
 private Room room(){Room r=new Room();r.wave=17;r.spawns[17]=128;r.ready=138;r.player=RangerStrategy.tile(3293,4248);parent=new Crab(51,51,84,12,Lane.SOUTH,'W',true,Style.MELEE,RangerStrategy.tile(3292,4243));parent.pendingDamage=0;r.crabs.add(parent);return r;}
 @Test public void nativeIdleAgeFiftyThreeStagesBothKnownChildSquares(){Room r=room();Decision d=new RangerStrategy().decide(r,137);assertNull(d.target);assertNull(d.approach);assertEquals(RangerStrategy.tile(3292,4244),d.tile);assertEquals("Prepare natural South12 children @139",d.reason);}
 @Test public void twoPrebirthMovesAllowAnImmediateActualMeleeScratch(){Room r=room();RangerStrategy s=new RangerStrategy();s.decide(r,137);r.player=RangerStrategy.tile(3292,4246);r.ready=139;assertEquals(RangerStrategy.tile(3292,4244),s.decide(r,138).tile);r.player=RangerStrategy.tile(3292,4244);r.crabs.clear();Crab child=new Crab(85,85,139,17,Lane.SPLIT,(char)0,false,Style.MELEE,RangerStrategy.tile(3292,4243));child.pendingDamage=0;r.crabs.add(child);Decision d=s.decide(r,139);assertSame(d.reason,child,d.target);assertEquals(Weapon.CLAWS,d.weapon);assertFalse(d.special);}
 @Test public void cooldownCanBeFreeButCannotRunTooFarPastTheBirth(){Room r=room();r.ready=141;assertEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,137).reason);r.ready=142;assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,137).reason);}
 @Test public void existingActualSmallFollowupIsNeverDisplaced(){Room r=room();Crab small=new Crab(80,80,132,17,Lane.SPLIT,(char)0,false,Style.RANGE,RangerStrategy.tile(3293,4248));small.pendingDamage=0;small.hp=3;r.crabs.add(small);RangerStrategy s=new RangerStrategy();s.attacked(new Decision(small,Weapon.PIPE,r.player,false,null,"actual"),136);Decision d=s.decide(r,137);assertTrue(d.reason,d.target==small||d.approach==small);assertNotEquals("Prepare natural South12 children @139",d.reason);}
 @Test public void unknownOrLethalOrMovingAnchorDoesNotInventNaturalChildren(){for(int g=0;g<3;g++){Room r=room();if(g==0)parent.pendingDamage=-1;if(g==1)parent.pendingDamage=16;if(g==2)parent.point=RangerStrategy.tile(3293,4243);assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,137).reason);}}
 @Test public void cannotBeginAnUnfinishableLateApproachOrWaitPastBirth(){Room r=room();r.ready=138;assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,138).reason);r=room();assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,139).reason);}
 @Test public void imminentOriginalNineteenEyeReservesItsFullCooldown(){Room r=room();r.wave=19;r.spawns[19]=136;r.ready=138;assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,137).reason);}
 @Test public void southFifteenUsesItsOwnKnownBirthAndTwentyBowBudget(){Room r=room();r.crabs.clear();r.wave=19;r.spawns[19]=152;r.ready=162;parent=new Crab(72,72,108,15,Lane.SOUTH,'W',true,Style.MAGIC,RangerStrategy.tile(3292,4243));parent.pendingDamage=0;r.crabs.add(parent);assertEquals("Prepare natural South15 children @163",new RangerStrategy().decide(r,161).reason);}
 @Test public void farFutureOrWrongParentHasNoNewStaging(){Room r=room();assertNotEquals("Prepare natural South12 children @139",new RangerStrategy().decide(r,136).reason);r=room();r.crabs.clear();Crab other=new Crab(61,61,84,13,Lane.EAST,'S',true,Style.MELEE,RangerStrategy.tile(3292,4243));other.pendingDamage=0;r.crabs.add(other);assertNotEquals("Prepare natural South13 children @139",new RangerStrategy().decide(r,137).reason);}
}